<?php $this->layout('_studio'); $first=strtotime($month.'-01'); $start=(int)date('N',$first); $days=(int)date('t',$first); $byDay=[]; foreach($events as $event){$byDay[(int)date('j',strtotime($event->starts_at))][]=$event;} ?>
<section class="organic-page-header"><div><p class="organic-eyebrow">Atendimento</p><h1 class="organic-page-title">Agenda</h1><p class="organic-page-description">Organize atendimentos, tarefas e compromissos do time em uma visão mensal.</p></div><button class="organic-btn organic-btn-primary" type="button" data-organic-modal-open="#agenda-event-modal"><ion-icon name="add-outline"></ion-icon>Novo evento</button></section>
<section class="organic-card studio-agenda"><header class="organic-card-header"><a class="organic-btn organic-btn-icon" href="<?= url('/studio/agenda?month='.date('Y-m',strtotime($month.'-01 -1 month'))) ?>" aria-label="Mês anterior"><ion-icon name="chevron-back-outline"></ion-icon></a><h2 class="organic-card-title"><?= ucfirst(strftime('%B de %Y',$first)) ?></h2><a class="organic-btn organic-btn-icon" href="<?= url('/studio/agenda?month='.date('Y-m',strtotime($month.'-01 +1 month'))) ?>" aria-label="Próximo mês"><ion-icon name="chevron-forward-outline"></ion-icon></a></header><div class="studio-agenda-weekdays"><span>Seg</span><span>Ter</span><span>Qua</span><span>Qui</span><span>Sex</span><span>Sáb</span><span>Dom</span></div><div class="studio-agenda-grid"><?php for($cell=1;$cell<$start+$days;$cell++): $day=$cell-$start+1; ?><div class="studio-agenda-day"><strong><?= $day ?></strong><?php foreach($byDay[$day]??[] as $event): ?><article class="<?= htmlspecialchars($event->type) ?>" title="<?= htmlspecialchars($event->description??'') ?>"><span><?= date('H:i',strtotime($event->starts_at)) ?></span><?= htmlspecialchars($event->title) ?></article><?php endforeach;?></div><?php endfor;?></div></section>
